'use strict';
window.FolderSave=(()=>{
 const boot=window.FolderBootstrap,enabled=!!boot?.enabled,pending=new Map(),assets=new Set();let running=null,error='',retry,ticket=0;
 function notice(){let el=document.getElementById('folder-save-status');if(!el){el=document.createElement('p');el.id='folder-save-status';el.setAttribute('role','status');document.querySelector('main')?.prepend(el)}if(!el)return;el.className='folder-status '+(error?'save-error':'');el.textContent=boot?.error||(!enabled?'Browser-only mode · use the game launcher to save into the game folder.':error?'Folder save failed — '+error+' Please keep this page open and try again.':pending.size||running||assets.size?'Saving to game folder…':'Saved in game folder · data/game.json')}
 async function request(path,options={}){const r=await fetch(path,{...options,headers:{'X-Game-Save':'1',...options.headers}});if(!r.ok){let problem;try{problem=(await r.json()).error}catch{}throw Error(problem||'The local game server could not save.')}return r}
 function write(key,value){if(!enabled)return;boot[key]=value;pending.set(key,{value,version:++ticket});error='';clearTimeout(retry);notice();pump()}
 function pump(){if(!enabled||running||!pending.size)return running||Promise.resolve();const batch=new Map(pending),patch=Object.fromEntries([...batch].map(([k,v])=>[k,v.value]));running=request('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(patch)}).then(()=>{for(const [key,v]of batch)if(pending.get(key)?.version===v.version)pending.delete(key);error=''}).catch(e=>{error=e.message;retry=setTimeout(pump,3000)}).finally(()=>{running=null;notice();if(!error&&pending.size)pump()});return running}
 function track(promise){const watched=Promise.resolve(promise).catch(e=>{error=e.message;throw e}).finally(()=>{assets.delete(watched);notice()});assets.add(watched);watched.catch(()=>{});notice();return watched}
 async function flush(){if(!enabled)return;if(assets.size)await Promise.all([...assets]);clearTimeout(retry);while(pending.size||running){await(running||pump());if(error)throw Error(error)}}
 async function navigate(url){try{await flush();location.href=url}catch(e){notice();alert('The folder save has not finished. Please keep this page open and try again. '+e.message)}}
 const audio={async list(){return (await request('/api/audio')).json()},async get(clip){return(await request('/api/audio/'+encodeURIComponent(clip.id))).blob()},async put(id,name,blob){await track(request('/api/audio/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':blob.type||'audio/webm','X-Clip-Name':encodeURIComponent(name)},body:blob}))},async remove(id){await track(request('/api/audio/'+encodeURIComponent(id),{method:'DELETE'}))}};
 document.addEventListener('click',e=>{const a=e.target.closest?.('a[href]');if(!enabled||!a||e.button!==0||e.ctrlKey||e.metaKey||a.target||a.download||!pending.size&&!running&&!assets.size)return;const url=new URL(a.href,location.href);if(url.origin===location.origin){e.preventDefault();navigate(a.href)}});
 window.addEventListener('beforeunload',e=>{if(enabled&&(pending.size||running||assets.size)){e.preventDefault();e.returnValue=''}});
 notice();return {enabled,track,read:key=>enabled?boot[key]:null,write,flush,navigate,audio,get pending(){return !!(pending.size||running||assets.size)}};
})();
